import json
import shlex
import pathlib

# Patch compile_commands.json generated by nvcc to be usable by clangd

src = pathlib.Path("build/compile_commands.json")
# dst = pathlib.Path("build/compile_commands_clangd.json")

drop_prefixes = (
    "-forward-unknown-to-host-compiler",
    "--options-file",
    "--generate-code",
    "-Xcompiler=",
    "-rdc",
    "--expt-extended-lambda",
    "--expt-relaxed-constexpr",
    "--device-c",
    "--device-link",
    "-dlink",
)


def patch(cmd):
    parts = shlex.split(cmd)
    if parts and parts[0].endswith("nvcc"):
        parts[0] = "clang++"

    new = []
    skip = False
    for p in parts[1:]:
        if skip:
            skip = False
            continue
        if p == "--options-file":
            skip = True
            continue
        if p.startswith(drop_prefixes):
            continue
        new.append(p)

    if "-x" not in new:
        new = ["-x", "cuda"] + new
    return " ".join([parts[0]] + new)


cc = json.loads(src.read_text())
for e in cc:
    e["command"] = patch(e["command"])

src.write_text(json.dumps(cc, indent=2))
